export function HeroBlock({ eyebrow = "Independent digital studio", title = "Make room for the remarkable.", description = "We partner with thoughtful teams to turn ambitious ideas into clear, useful digital experiences.", className = "" }: { eyebrow?: string; title?: string; description?: string; className?: string }) {
  return <section aria-labelledby="field-hero-title" className={`relative isolate w-full overflow-hidden border border-border bg-background px-6 py-16 text-foreground sm:px-10 sm:py-24 lg:px-16 ${className}`}>
    <div aria-hidden="true" className="absolute inset-y-0 right-0 -z-10 w-2/3 bg-linear-to-br from-primary/15 via-background to-muted/40" />
    <div className="max-w-3xl"><p className="font-mono text-[10px] uppercase tracking-[.24em] text-primary">{eyebrow}</p><h1 id="field-hero-title" className="mt-6 max-w-3xl text-5xl font-light leading-[1.03] tracking-[-.055em] sm:text-7xl">{title}</h1><p className="mt-6 max-w-xl text-base leading-7 text-muted-foreground">{description}</p><div className="mt-8 flex flex-wrap gap-3"><a href="#work" className="inline-flex items-center gap-3 bg-primary px-5 py-3 text-sm font-medium text-primary-foreground hover:bg-primary/90 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring">Explore our work <span aria-hidden="true">↗</span></a><a href="#studio" className="inline-flex items-center border border-border px-5 py-3 text-sm hover:bg-accent focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-ring">Meet the studio</a></div></div>
    <div aria-hidden="true" className="mt-16 flex max-w-3xl items-end gap-2 border-b border-border pb-3 font-mono text-[10px] uppercase tracking-widest text-muted-foreground"><span>Selected work</span><span className="mb-1 h-px flex-1 bg-border" /><span>2024 — 2026</span></div>
  </section>;
}
